  b1RetryExplainNegotiateDemand: "That works, but sounds like a demand — try a softer frame like \"would it be possible to...\".",
  b1RetryExplainNegotiateUnderdeveloped: "Good start — now make it a full, polite request, like \"would it be possible to...\" or \"could I possibly...\".",
  b1RetryPromptNegotiateFrame: "Try \"would it be possible to...\" or \"could I possibly...\".",
  b1Ep15Title: "What's the Plan",
  b1Ep15Goal: "Choose correctly between a spontaneous decision, a plan, and a prediction.",
  b1Ep15CanDoName: "Talk about plans and intentions",
  b1Ep15Duration: "10 min",
  b1Ep15SceneTitle: "Three kinds of future",
  b1Ep15SceneBody: "You already know one way to talk about the future. Now let's tell the difference between a decision, a plan, and a prediction.",
  b1Ep15ModelExplain: "\"I'll\" is a decision made now; \"I'm going to\" is a plan made earlier; \"will\" also predicts.",
  b1Ep15ComprehensionInstruction: "Which sentence is a plan decided before now, not a decision made this second?",
  b1Ep15CompOptCorrect: "I'm going to visit my sister next week.",
  b1Ep15CompOptWrong1: "I'll have the pasta, thanks.",
  b1Ep15CompOptWrong2: "It will probably rain later.",
  b1Ep15BlankInstruction: "Complete the sentence.",
  b1Ep15BlankHint: "Two words, a contraction of \"I will\".",
  b1Ep15OpenInstruction: "Decide right now, and say what you'll have.",
  b1Ep15OpenInstruction2: "Tell me about a plan you already made.",
  b1Ep15OpenInstruction3: "Make a prediction about tomorrow's weather.",
  b1Ep16Title: "Someday",
  b1Ep16Goal: "Say what you hope or want to do in the future, with no fixed date.",
  b1Ep16CanDoName: "Talk about hopes and ambitions",
  b1Ep16Duration: "8 min",
  b1Ep16SceneTitle: "Beyond the calendar",
  b1Ep16SceneBody: "A plan has a date. A hope doesn't — let's talk about those too.",
  b1Ep16ModelExplain: "\"I hope to\", \"I'd like to\" and \"one day I'll\" all talk about a hope, not a scheduled plan.",
  b1Ep16ComprehensionInstruction: "Which sentence is a hope with no fixed date, not a plan for next week?",
  b1Ep16CompOptCorrect: "I hope to travel more one day.",
  b1Ep16CompOptWrong1: "I'm going to travel next month.",
  b1Ep16CompOptWrong2: "I'll travel tomorrow.",
  b1Ep16BlankInstruction: "Complete the sentence.",
  b1Ep16BlankHint: "Three words.",
  b1Ep16OpenInstruction: "Tell me a hope of yours.",
  b1Ep16OpenInstruction2: "A different hope now.",
  b1Ep17Title: "If That Happens",
  b1Ep17Goal: "Say what will happen if a real, likely condition is met.",
  b1Ep17CanDoName: "Talk about real conditions",
  b1Ep17Duration: "7 min",
  b1Ep17SceneTitle: "A likely \"if\"",
  b1Ep17SceneBody: "Some things depend on other things. Let's say what happens if they do.",
  b1Ep17ModelExplain: "\"If\" + present tense, then \"will\" + verb, for something that could really happen.",
  b1Ep17ComprehensionInstruction: "Which sentence correctly says what will happen if a real condition is met?",
  b1Ep17CompOptCorrect: "If it rains tomorrow, I'll stay home.",
  b1Ep17CompOptWrong1: "It rains a lot here.",
  b1Ep17CompOptWrong2: "If I were rich, I'd travel more.",
  b1Ep17BlankInstruction: "Complete the sentence.",
  b1Ep17BlankHint: "One word.",
  b1Ep17OpenInstruction: "What will you do if it rains this weekend?",
  b1Ep18Title: "If I Were You",
  b1Ep18Goal: "Give simple advice using a fixed hypothetical frame.",
  b1Ep18CanDoName: "Imagine a hypothetical",
  b1Ep18Duration: "7 min",
  b1Ep18SceneTitle: "A little bit of advice",
  b1Ep18SceneBody: "Here's one more useful frame — imagining you were in someone else's place.",
  b1Ep18ModelExplain: "\"If I were you, I'd...\" gives advice about an imagined situation, not a real condition.",
  b1Ep18ComprehensionInstruction: "Which sentence gives hypothetical advice with \"if I were you\"?",
  b1Ep18CompOptCorrect: "If I were you, I'd ask for a refund.",
  b1Ep18CompOptWrong1: "If it happens again, I will ask for a refund.",
  b1Ep18CompOptWrong2: "You should ask for a refund.",
  b1Ep18BlankInstruction: "Complete the sentence.",
  b1Ep18BlankHint: "Four words.",
  b1Ep18OpenInstruction: "What would you tell your friend?",
  b1RetryPromptFutureEmpty: "Tell me your decision, plan, or prediction.",
  b1PraiseFutureIndependent: "Great — exactly the right form for that situation.",
  b1PraiseFutureHelped: "Nice — that matches the situation.",
  b1RetryExplainFuturePast: "This is about the future, so use \"will\" or \"going to\", not the past.",
  b1RetryPromptFuturePast: "Try again, talking about the future.",
  b1RetryExplainFutureFunction: "That form is correct English, but not for this situation — check if it's a decision, a plan, or a prediction.",
