  b1Ep19Title: "Changing the Subject",
  b1Ep19Goal: "Change the subject politely, or follow someone else's change.",
  b1Ep19CanDoName: "Change the topic",
  b1Ep19Duration: "9 min",
  b1Ep19SceneTitle: "More than one thing to talk about",
  b1Ep19SceneBody: "A real conversation moves between topics. Let's learn how to move it, politely.",
  b1Ep19ModelExplain: "\"Anyway\", \"by the way\" and \"speaking of\" all signal a change of subject.",
